def validate_records(mapping):
    records = mapping.get('records')
    valid = type(records) is list and 1 <= len(records) <= 3
    if valid:
        for item in records:
            if type(item) is not dict or set(item) != {'code', 'enabled'}:
                valid = False
                break
            if not (type(item['code']) is str and 2 <= len(item['code']) <= 5 and type(item['enabled']) is bool):
                valid = False
                break
    result = {'ok': valid, 'records': records if valid else []}
